public interface IImageFilter { byte[] Apply(byte[] imageData); }

public class FilterPipeline
{
    private readonly List<IImageFilter> _filters = new();

    public byte[] Process(byte[] original)
    {
        var result = original;
        foreach (var filter in _filters)
            result = filter.Apply(result);
        return result;
    }
}

// Example filters
